package fable.hideseek.imba.client;import fable.hideseek.imba.net.MessageSettingsNetworking;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import java.util.HashMap;public final class MessageSettingsClientNetworking{private MessageSettingsClientNetworking(){}public static void register(){ClientPlayNetworking.registerGlobalReceiver(MessageSettingsNetworking.SYNC,(client,handler,buf,sender)->{int count=Math.max(0,Math.min(256,buf.readVarInt()));var next=new HashMap<String,Boolean>();for(int i=0;i<count;i++)next.put(buf.readString(128),buf.readBoolean());client.execute(()->{MessageSettingsClientData.replace(next);if(client.currentScreen instanceof MessageSettingsScreen screen)screen.applyServerState();});});}}
